import React, { useRef, useEffect } from "react";
import * as THREE from "three";
import styled, { keyframes } from "styled-components"; // Import styled and keyframes
import { useThreeJS } from "../hooks/useThreeJS";
import { useAppContext } from "../context/AppContext";

// Styled Components
const ViewerWrapper = styled.div`
  position: relative;
  width: 100%;
  height: 100vh;
  overflow: hidden;
  background-color: #1a202c; /* bg-space-dark - Reverted to original */
`;

const ThreeContainer = styled.div`
  width: 100%;
  height: 100%;
  cursor: grab;
  &:active {
    cursor: grabbing;
  }
  outline: none;
  position: relative; /* Added for z-index context */
  z-index: 1; /* Added to ensure it's on top of other elements within ViewerWrapper if any */
`;

const LoadingOverlay = styled.div`
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #1a202c; /* bg-space-dark */
`;

const LoadingTextContainer = styled.div`
  text-align: center;
`;

const spinAnimation = keyframes`
  to {
    transform: rotate(360deg);
  }
`;

const Spinner = styled.div`
  animation: ${spinAnimation} 1.5s linear infinite; /* animate-spin-slow - adjusted duration */
  width: 4rem; /* w-16 */
  height: 4rem; /* h-16 */
  border: 4px solid #3b82f6; /* border-4 border-blue-500 */
  border-top-color: transparent; /* border-t-transparent */
  border-radius: 50%; /* rounded-full */
  margin-bottom: 1rem; /* mb-4 */
`;

const LoadingText = styled.p`
  font-size: 1.25rem; /* text-xl */
  color: #d1d5db; /* text-gray-300 */
`;

const PerformanceIndicator = styled.div`
  position: absolute;
  bottom: 1rem; /* bottom-4 */
  right: 1rem; /* right-4 */
  font-size: 0.75rem; /* text-xs */
  color: #9ca3af; /* text-gray-400 */
  background-color: rgba(0, 0, 0, 0.5); /* bg-black bg-opacity-50 */
  padding: 0.25rem 0.5rem; /* px-2 py-1 */
  border-radius: 0.25rem; /* rounded */
`;

const EarthViewer = () => {
  const containerRef = useRef(null);
  const { state, dispatch } = useAppContext();
  const { scene, renderer, camera, earth, isInitialized } =
    useThreeJS(containerRef);

  // Handle mouse interactions
  useEffect(() => {
    if (!containerRef.current || !isInitialized) return;

    let isMouseDown = false;
    let previousMousePosition = { x: 0, y: 0 };

    const handleMouseDown = (event) => {
      isMouseDown = true;
      previousMousePosition = {
        x: event.clientX,
        y: event.clientY,
      };
    };

    const handleMouseUp = () => {
      isMouseDown = false;
    };

    const handleMouseMove = (event) => {
      if (!isMouseDown || !earth) return;

      const deltaMove = {
        x: event.clientX - previousMousePosition.x,
        y: event.clientY - previousMousePosition.y,
      };

      const deltaRotationQuaternion = new THREE.Quaternion().setFromEuler(
        new THREE.Euler(deltaMove.y * 0.01, deltaMove.x * 0.01, 0, "XYZ")
      );

      earth.quaternion.multiplyQuaternions(
        deltaRotationQuaternion,
        earth.quaternion
      );

      previousMousePosition = {
        x: event.clientX,
        y: event.clientY,
      };
    };

    const handleWheel = (event) => {
      if (!camera) return;

      event.preventDefault();
      const scale = event.deltaY > 0 ? 1.1 : 0.9;

      camera.position.multiplyScalar(scale);

      // Clamp zoom limits
      const distance = camera.position.length();
      if (distance < 2) {
        camera.position.normalize().multiplyScalar(2);
      } else if (distance > 10) {
        camera.position.normalize().multiplyScalar(10);
      }
    };

    const element = containerRef.current;
    element.addEventListener("mousedown", handleMouseDown);
    element.addEventListener("mouseup", handleMouseUp);
    element.addEventListener("mousemove", handleMouseMove);
    element.addEventListener("wheel", handleWheel);

    return () => {
      element.removeEventListener("mousedown", handleMouseDown);
      element.removeEventListener("mouseup", handleMouseUp);
      element.removeEventListener("mousemove", handleMouseMove);
      element.removeEventListener("wheel", handleWheel);
    };
  }, [isInitialized, earth, camera]);

  return (
    <ViewerWrapper>
      {/* Three.js container */}
      <ThreeContainer
        ref={containerRef}
        // className="w-full h-full cursor-grab active:cursor-grabbing" // Removed
        // style={{ outline: "none" }} // Handled by styled component
      />

      {/* Loading indicator */}
      {!isInitialized && (
        <LoadingOverlay>
          <LoadingTextContainer>
            <Spinner />
            <LoadingText>Loading Earth...</LoadingText>
          </LoadingTextContainer>
        </LoadingOverlay>
      )}

      {/* Performance indicator */}
      <PerformanceIndicator>
        WebGL Enabled: {isInitialized ? "✓" : "✗"}
      </PerformanceIndicator>
    </ViewerWrapper>
  );
};

export default EarthViewer;
